package com.bluecash.wallet.core

/**
 * DEMO ONLY. These are the keys of the *simulated* mint that runs inside the app so the whole
 * flow works with no backend. The private halves are embedded here, so anyone can mint money
 * with them. That is acceptable for a demo and unacceptable anywhere real: the real mint is
 * Person A's server, which keeps its private keys in an HSM.
 *
 * Every install embeds the SAME keys, so tokens minted on one phone verify on another.
 */
object DemoMintKeys {
    val edSeed: ByteArray = "4e3dba0bf8320025bd8ac5dd84f9257e9e71a5bd39bf4e0227c0ecc0e99f2f93".unhex()
    // Valid until 2027-12-31 (UTC).
    const val EXPIRY_MS = 1830211200000L

    private const val N10 = ""
    private const val E10 = "10001"
    private const val D10 = ""
    private const val N50 = ""
    private const val E50 = "10001"
    private const val D50 = ""
    private const val N100 = ""
    private const val E100 = "10001"
    private const val D100 = ""
    private const val N500 = ""
    private const val E500 = "10001"
    private const val D500 = ""

    val keys: List<MintKey> = listOf(
        MintKey("d10-2027", 10, "INR", EXPIRY_MS, N10, E10),
        MintKey("d50-2027", 50, "INR", EXPIRY_MS, N50, E50),
        MintKey("d100-2027", 100, "INR", EXPIRY_MS, N100, E100),
        MintKey("d500-2027", 500, "INR", EXPIRY_MS, N500, E500),
    )

    fun privateExponent(keyId: String): java.math.BigInteger? = when (keyId) {
        "d10-2027" -> bigFromHex(D10)
        "d50-2027" -> bigFromHex(D50)
        "d100-2027" -> bigFromHex(D100)
        "d500-2027" -> bigFromHex(D500)
        else -> null
    }
}
